/**
 * Called when the lexer is inside a JSX mode and encounters a '{' that
 * starts a JSX expression. The mode stack must be unwound back to the
 * JSX mode when the matching '}' is lexed in the default mode.
 */
protected void BeginJsxExpression() {
    this.jsxExpressionBraces.push(1);
}

/**
 * Increment the brace nesting level of the innermost open JSX expression
 * when a nested '{' is lexed while inside a JSX expression.
 */
protected void IncreaseJsxExpressionDepth() {
    if (!this.jsxExpressionBraces.isEmpty()) {
        int depth = this.jsxExpressionBraces.pop();
        this.jsxExpressionBraces.push(depth + 1);
    }
}

/**
 * Returns true iff the next '}' closes the innermost open JSX expression,
 * i.e. there are no nested JS braces still open inside of it.
 */
protected boolean IsJsxExpressionEnd() {
    return !this.jsxExpressionBraces.isEmpty() && this.jsxExpressionBraces.peek() == 1;
}

/**
 * Removes the innermost open JSX expression's brace counter after the
 * expression has been closed by a '}' that also pops the lexer mode.
 */
protected void EndJsxExpression() {
    if (!this.jsxExpressionBraces.isEmpty()) {
        this.jsxExpressionBraces.pop();
    }
}

protected boolean IsJsxPossible() {
    if (this.lastToken == null) {
        return true;
    }
    switch (this.lastToken.getType()) {
        case JavaScriptLexer.Assign:
        case JavaScriptLexer.Colon:
        case JavaScriptLexer.Comma:
        case JavaScriptLexer.Default:
        case JavaScriptLexer.QuestionMark:
        case JavaScriptLexer.Return:
        case JavaScriptLexer.OpenBrace:
        case JavaScriptLexer.OpenParen:
        case JavaScriptLexer.Yield:
        case JavaScriptLexer.ARROW:
        case JavaScriptLexer.JsxOpeningElementSlashEnd:
        case JavaScriptLexer.JsxClosingElementEnd:
        case JavaScriptLexer.CloseBrace:
        case JavaScriptLexer.CloseParen:
            return true;
        default:
            return false;
    }
}
