    protected void BeginJsxExpression() {
        this.jsxExpressionBraces.push(1);
    }

    /**
     * Increments the brace nesting level of the innermost open JSX
     * expression. Called when a nested `{` is lexed in the default mode while
     * a JSX expression is being lexed.
     */
    protected void IncreaseJsxExpressionDepth() {
        if (!this.jsxExpressionBraces.isEmpty()) {
            int depth = this.jsxExpressionBraces.pop();
            this.jsxExpressionBraces.push(depth + 1);
        }
    }

    /**
     * Decrements the brace nesting level of the innermost open JSX
     * expression. Called when a `}` is lexed in the default mode while
     * nested JavaScript braces are still open inside a JSX expression.
     */
    protected void DecreaseJsxExpressionDepth() {
        if (!this.jsxExpressionBraces.isEmpty()) {
            int depth = this.jsxExpressionBraces.pop();
            if (depth > 1) {
