#!/usr/bin/env python3
"""ANTLR-faithful simulation of the rewritten javascript/jsx lexer modes.

Models the mode stack, the JSX expression brace stack, the IsJsxPossible gate,
and rule ordering/longest-match behavior enough to verify that:
  - every input tokenizes (no rule falls through),
  - the mode stack winds back to DEFAULT at end of file,
  - the JSX expression brace stack is empty at end of file,
  - no keyword leakage / no regex mis-match for the target scenarios.
"""

import re
import sys

DEFAULT = 'DEFAULT'
OPENING = 'JSX_OPENING_ELEMENT'
CHILDREN = 'JSX_CHILDREN'
CLOSING = 'JSX_CLOSING_ELEMENT'

WS = 'WsHidden'
KEYWORDS = {
    'default': 'Default', 'return': 'Return', 'yield': 'Yield', 'in': 'In',
    'import': 'Import', 'from': 'From', 'class': 'Class', 'true': 'BooleanLiteral',
    'false': 'BooleanLiteral', 'null': 'NullLiteral', 'this': 'This', 'new': 'New',
    'instanceof': 'Instanceof', 'typeof': 'Typeof', 'void': 'Void', 'delete': 'Delete',
    'function': 'Function_', 'let': 'NonStrictLet', 'const': 'Const', 'var': 'Var',
    'async': 'Async', 'await': 'Await', 'super': 'Super', 'if': 'If', 'else': 'Else',
    'switch': 'Switch', 'case': 'Case', 'while': 'While', 'for': 'For', 'do': 'Do',
    'break': 'Break', 'continue': 'Continue', 'throw': 'Throw', 'try': 'Try',
    'catch': 'Catch', 'finally': 'Finally', 'with': 'With', 'debugger': 'Debugger',
    'static': 'Static', 'extends': 'Extends', 'export': 'Export'
}

JSX_PRECEDING = {
    'Assign', 'OpenBracket', 'Colon', 'Comma', 'Default', 'QuestionMark',
    'Return', 'OpenBrace', 'OpenParen', 'Yield', 'ARROW', 'And', 'Or',
    'JsxOpeningElementSlashEnd', 'JsxClosingElementEnd',
}


class Lex:
    def __init__(self, text):
        self.s = text
        self.i = 0
        self.n = len(text)
        self.mode = DEFAULT
        self.stack = []
        self.markers = []
        self.last = None  # last default-channel token type
        self.types = []
        self.errors = []
        self.emit = []
        self.template_depth = 0

    def is_jsx_possible(self):
        return self.last is None or self.last in JSX_PRECEDING

    def peek(self, off=0):
        j = self.i + off
        return self.s[j] if j < self.n else ''

    def err(self, msg):
        self.errors.append(f"@{self.i} in {self.mode}: {msg}")
        return False

    def push(self, m):
        self.stack.append(self.mode)
        self.mode = m
        return True

    def pop(self):
        if not self.stack:
            self.err("popMode on empty stack")
            return False
        self.mode = self.stack.pop()
        return True

    def emit_type(self, typ, consumed=None, hidden=False):
        if consumed is None:
            consumed = self.i
        if not hidden:
            self.last = typ
            self.types.append(typ)
        self.emit.append((typ, self.s[consumed:self.i], self.mode))
        return True

    # ---- helpers ----
    def match_id(self):
        m = re.match(r'[A-Za-z_$][A-Za-z0-9_$]*', self.s[self.i:])
        if not m:
            return None
        return m.group(0)

    def match_str(self, q):
        j = self.s.find(q, self.i + 1)
        if j < 0:
            return None
        return self.s[self.i:j + 1]

    # ---- main loop ----
    def step(self):
        if self.i >= self.n:
            return False
        m = self.mode
        if m == OPENING:
            return self.step_opening()
        if m == CHILDREN:
            return self.step_children()
        if m == CLOSING:
            return self.step_closing()
        return self.step_default()

    def step_default(self):
        c = self.peek()
        rest = self.s[self.i:]

        if c in ' \t\r\n\f\v\u00a0':
            m = re.match(r'[\t\r\n\u000B\u000C\u0020\u00A0]+', rest)
            self.i += len(m.group(0)); return self.emit_type(WS, hidden=True)

        # JsxCloseBrace: gated } that pops back to the JSX mode
        if c == '}' and self.markers and self.markers[-1] == 1:
            self.markers.pop()
            start = self.i
            self.i += 1
            self.emit_type('JsxCloseBrace' if False else 'CloseBrace', consumed=start)
            self.pop()
            return True

        if c == '}':  # CloseBrace (decrements marker depth if any)
            if self.markers:
                self.markers[-1] -= 1
            start = self.i; self.i += 1
            self.emit_type('CloseBrace', consumed=start)
            return True

        if rest.startswith('=>'):
            self.i += 2; return self.emit_type('ARROW')
        if rest.startswith('&&'):
            self.i += 2; return self.emit_type('And')
        if rest.startswith('||'):
            self.i += 2; return self.emit_type('Or')
        if rest.startswith('...'):
            self.i += 3; return self.emit_type('Ellipsis')

        if c == '<':
            if self.is_jsx_possible():
                self.i += 1
                self.emit_type('JsxElementBegin')
                return self.push(OPENING)
            self.i += 1; return self.emit_type('LessThan')

        if c == '>':
            self.i += 1; return self.emit_type('MoreThan')
        if c == '=':
            self.i += 1; return self.emit_type('Assign')
        if c == '[':
            self.i += 1; return self.emit_type('OpenBracket')
        if c == ']':
            self.i += 1; return self.emit_type('CloseBracket')
        if c == '(':
            self.i += 1; return self.emit_type('OpenParen')
        if c == ')':
            self.i += 1; return self.emit_type('CloseParen')
        if c == ',':
            self.i += 1; return self.emit_type('Comma')
        if c == ':':
            self.i += 1; return self.emit_type('Colon')
        if c == '?':
            self.i += 1; return self.emit_type('QuestionMark')
        if c == ';':
            self.i += 1; return self.emit_type('SemiColon')
        if c == '{':
            if self.markers:
                self.markers[-1] += 1
            self.i += 1; return self.emit_type('OpenBrace')
        if c in '+-*/%&|^~!.':
            self.i += 1
            return self.emit_type('Opr' + c)
        if c in '"\'':
            s = self.match_str(c)
            if s is None:
                return self.err("unterminated string")
            self.i += len(s); return self.emit_type('StringLiteral')
        if rest.startswith('//'):
            j = rest.find('\n')
            self.i += len(rest[:j]) if j >= 0 else len(rest)
            return self.emit_type(WS, hidden=True)
        if rest.startswith('/*'):
            j = rest.find('*/')
            if j < 0:
                return self.err("unterminated comment")
            self.i += j + 2; return self.emit_type(WS, hidden=True)
        if c.isdigit():
            m = re.match(r'[0-9]+', rest)
            self.i += len(m.group(0)); return self.emit_type('DecimalLiteral')
        if c.isalpha() or c in '_$':
            w = self.match_id()
            self.i += len(w)
            return self.emit_type(KEYWORDS.get(w, 'Identifier'))
        if c == '`':
            self.i += 1
            if self.template_depth == 0:
                self.template_depth += 1
            else:
                self.template_depth -= 1
            return self.emit_type('BackTick')
        return self.err(f"unexpected char {c!r}")

    def step_opening(self):
        rest = self.s[self.i:]
        c = self.peek()

        if c in ' \t\r\n\f\v\u00a0':
            m = re.match(r'[\t\r\n\u000B\u000C\u0020\u00A0]+', rest)
            self.i += len(m.group(0)); return self.emit_type(WS, hidden=True)

        # tokens by literal length order to mimic longest-match
        if rest.startswith('{/*'):
            j = rest.find('*/}')
            if j >= 0:
                self.i += j + 3; return self.emit_type(WS, hidden=True)
        if rest.startswith('/*'):
            j = rest.find('*/')
            if j >= 0:
                self.i += j + 2; return self.emit_type(WS, hidden=True)
        if rest.startswith('//'):
            j = rest.find('\n')
            self.i += len(rest[:j]) if j >= 0 else len(rest)
            return self.emit_type(WS, hidden=True)
        if rest.startswith('/>') or c == '/':
            # Slave slash end: '/>' two chars beats any single-char rule
            if rest.startswith('/>'):
                self.i += 2
                self.emit_type('JsxOpeningElementSlashEnd')
                return self.pop()
            self.i += 1; return self.emit_type('Divide')
        if c == '<':
            self.i += 1
            self.emit_type('JsxOpeningElementBegin')
            return self.push(OPENING)
        if c == '>':
            self.i += 1
            self.emit_type('JsxOpeningElementEnd')
            self.mode = CHILDREN
            return True
        if c == '=':
            self.i += 1; return self.emit_type('JsxAssign')
        if c == '{':
            self.markers.append(1)
            self.i += 1
            self.emit_type('JsxOpeningElementOpenBrace')
            return self.push(DEFAULT)
        if c in '"\'':
            s = self.match_str(c)
            if s is None:
                return self.err("unterminated attr string")
            self.i += len(s); return self.emit_type('JsxAttributeValue')
        if c.isalpha() or c in ':_':
            # JsxIdentifier (includes '-' '.' digits afterwards)
            m = re.match(r'[A-Za-z_:][A-Za-z0-9_*.:-]*', rest)
            self.i += len(m.group(0)); return self.emit_type('JsxOpeningElementId')
        if c.isdigit():  # DecChars/HexChars style attr values
            m = re.match(r'[0-9]+%?', rest)
            self.i += len(m.group(0)); return self.emit_type('JsxAttributeValue')
        if c == '#':
            m = re.match(r'#[0-9a-fA-F]+', rest)
            self.i += len(m.group(0)); return self.emit_type('JsxAttributeValue')
        return self.err(f"unexpected char in opening {c!r}")

    def step_children(self):
        rest = self.s[self.i:]
        if rest.startswith('{/*'):
            j = rest.find('*/}')
            if j >= 0:
                self.i += j + 3; return self.emit_type(WS, hidden=True)
        c = self.peek()
        if c == '<':
            if rest.startswith('</'):
                self.i += 2
                self.emit_type('JsxChildrenClosingElementSlashBegin')
                self.pop()
                return self.push(CLOSING)
            self.i += 1
            self.emit_type('JsxChildrenOpeningElementBegin')
            return self.push(OPENING)
        if c == '{':
            self.markers.append(1)
            self.i += 1
            self.emit_type('JsxChildrenOpenBrace')
            return self.push(DEFAULT)
        # HtmlChardata: any char except < and {
        m = re.match(r'[^<{]+', rest)
        self.i += len(m.group(0)); return self.emit_type('HtmlChardata')

    def step_closing(self):
        rest = self.s[self.i:]
        c = self.peek()
        if c in ' \t\r\n\f\v\u00a0':
            m = re.match(r'[\t\r\n\u000B\u000C\u0020\u00A0]+', rest)
            self.i += len(m.group(0)); return self.emit_type(WS, hidden=True)
        if rest.startswith('/*'):
            j = rest.find('*/')
            if j >= 0:
                self.i += j + 2; return self.emit_type(WS, hidden=True)
        if c == '>':
            self.i += 1
            self.emit_type('JsxClosingElementEnd')
            return self.pop()
        if c.isalpha() or c in ':_':
            m = re.match(r'[A-Za-z_:][A-Za-z0-9_*.:-]*', rest)
            self.i += len(m.group(0)); return self.emit_type('JsxClosingElementId')
        return self.err(f"unexpected char in closing {c!r}")

    def run(self):
        steps = 0
        while self.i < self.n and steps < 100000:
            if not self.step():
                break
            steps += 1
        if self.i < self.n:
            self.err("did not consume all input")
        ok = not self.errors and self.mode == DEFAULT and not self.stack and not self.markers
        return ok, self.emit, self.types


def check(name, text):
    lx = Lex(text)
    ok, emit, types = lx.run()
    status = "OK  " if ok else "FAIL"
    print(f"[{status}] {name}")
    if not ok:
        for e in lx.errors:
            print("     " + e[:200])
        print("     mode=%s stack=%s markers=%s last=%s" % (lx.mode, lx.stack, lx.markers, lx.last))
        print("     first 15 tokens:", emit[:15])
    return ok


def main():
    results = {}
    results['testcases_literal'] = check('TestCases.jsx FirstCase literal', 
        "const FirstCase = (\n  <div>\n    <div>\n      <div>deeply nested</div>\n    </div>\n  </div>\n);")
    results['testcases_kw'] = check('TestCases.jsx keyword leak', 
        "const KeywordText = (\n  <div>\n    from\n    import\n    return\n    class\n    default\n  </div>\n);")
    results['testcases_gt'] = check('TestCases.jsx attr > / &', 
        'const X = (<a href="https://example.com?a=1&b=2" title="a > b" data-size="10>20">link</a>);')
    results['testcases_expr'] = check('TestCases.jsx expression children', 
        "const X = (\n  <ul>\n    {items.map((item, index) => (\n      <li key={index}>{item.name}</li>\n    ))}\n  </ul>\n);")
    results['testcases_cond'] = check('TestCases.jsx conditional?/&&',
        "const X = (\n  <div>\n    {condition ? <span>yes</span> : <span>no</span>}\n    {condition && <span>also</span>}\n  </div>\n);")
    results['testcases_comment'] = check('TestCases.jsx comment children',
        "const X = (\n  <div>\n    {/* a comment */}\n    <span>text</span>\n  </div>\n);")
    results['testcases_props'] = check('TestCases.jsx props/spread',
        "const X = (<Component foo=\"bar\" baz={42} {...extraProps}>\n  Hello {name}!\n</Component>);")
    results['return_paren'] = check('return (<div><div></div></div>); | regex guard',
        "function f() { return (<div><div></div></div>); }")
    results['selfclose_chain'] = check('self-closing chain + arrays',
        "let a = [<A/>, <B/>]; const x = <div/><span/>;")
    results['switch'] = check('switch default: return <b/>',
        "function f(x) { switch (x) { case 1: return <a/>; default: return <b/>; } }")
    results['comparisons'] = check('comparisons not JSX',
        "if (a < b && c <= 5) { let y = x > 2 ? a << 2 : 0; }")
    results['regex'] = check('regex after return/(',
        "return /<div>/.test(s) ? m : (/<span>/.exec(s));")
    results['template_jsx'] = check('template inside jsx attr',
        "let x = (<JivePopover id={`option-field-${this.props.id}`} className=\"j2-x\">\n  <h4>{this.props.title}</h4>\n</JivePopover>);")
    results['obj_in_expr'] = check('object literal inside JSX expr',
        "const X = (<div title={{a:1}}>{fn({a: `x`})}</div>);")
    results['arrow_braces'] = check('arrow with block inside JSX expr',
        "const X = (<A>{items.map(x => { const y = x+1; return <b key={y}/>; })}</A>);")
    results['multiline_attrs'] = check('multiline attributes',
        "const X = (\n  <AutopositionOverlay\n    show={ this.state.show }  \n    target={ () => findDOMNode(this.refs.t) }\n    rootClose={ true }>\n    <span>hi</span>\n  </AutopositionOverlay>\n);")
    results['template_nested_plus'] = check('TemplateStrings.js content',
        "let str =\n    `${dsName}${parameterStr ? `( ${parameterStr} )` : \"\"}${returns ? `{\n${returns}}` : \"\"}`;")
    results['option_file_excerpt'] = check('OptionField.jsx render excerpt',
        "return (\n  <span>\n    <a ref=\"popoverToggle\" href=\"#\" onClick={ this.handlePopoverToggleClick.bind(this) }>\n      { this.props.value || this.props.title }\n    </a>\n  </span>\n);")
    results['file_input_excerpt'] = check('FileInput.jsx render excerpt',
        "return (\n  <form ref=\"form\" action={this.props.action} method=\"post\" encType=\"multipart/form-data\">\n    <label htmlFor={attributes.id} className={this.props.className}>\n      <FormattedMessage {...messages.editText}/>\n    </label>\n    <input ref=\"file\" { ...attributes } />\n  </form>\n);")

    bad = [k for k, v in results.items() if not v]
    print()
    print("PASS %d/%d" % (len(results) - len(bad), len(results)))
    if bad:
        print("FAILED:", bad)


if __name__ == '__main__':
    main()

